BEGIN;
-- Questions written for the earlier static GHS Mbonjo platform.
-- Generated by tools/load_authored.py. Run after db/phase7.sql.
--
-- Unlike the pamphlet import, these were written rather than scanned.
-- Every one carries a verified answer, an explanation, and a sentence
-- per wrong option saying why that choice is wrong. They arrive ready
-- to mark; there is nothing for a teacher to check.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_name='question_options' AND column_name='feedback') THEN
    RAISE EXCEPTION 'Run db/phase7.sql before this seed.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM syllabi WHERE form_level='Form 5' AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'No Form 5 syllabus found. Run db/seed/ first.';
  END IF;
END $$;

-- 80 questions
INSERT INTO questions (id, syllabus_id, question_text, question_type, marks, difficulty, source, source_year, source_paper, source_number, model_answer, marking_guide, scenario, auto_markable, needs_review, answer_origin, answer_confidence, import_batch)
SELECT x.id::uuid, target.id, x.question_text::text, x.question_type::text,
       x.marks::numeric, x.difficulty::text, x.source::text,
       x.source_year::integer, x.source_paper::text, x.source_number::text,
       x.model_answer::text, x.marking_guide::text, x.scenario::text,
       x.auto_markable::boolean, x.needs_review::boolean,
       x.answer_origin::text, x.answer_confidence::text, x.import_batch::text
FROM (VALUES
  ('abcdb80e-2c3d-5bc2-a85e-25315ef97e17', 'Which bus carries the location (address) of data in RAM to the CPU?', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '1', NULL, 'The Address Bus carries memory addresses — locations in RAM where data should be read from or written to. It is unidirectional (CPU to memory).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('41ba4c44-b393-59db-af61-433a87235507', 'Which component of the CPU executes decoded instructions during the machine cycle?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '2', NULL, 'The ALU performs all arithmetic (add, subtract) and logical (AND, OR, compare) operations — it executes decoded instructions.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('ad023219-e3b9-5e1d-b0e7-c7a9736fcd0b', 'Which type of memory loses its contents when the computer is switched off?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '3', NULL, 'RAM (Random Access Memory) is volatile — it loses all its contents when power is removed. This is why you must save your work before switching off.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('9ab8732f-947b-5e23-aef7-a3670a93cf04', 'What is the function of the Control Unit (CU) in the CPU?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '4', NULL, 'The Control Unit fetches instructions from memory, decodes them, and coordinates all CPU activities to ensure instructions are executed correctly.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('1d4ba5b2-5a44-5fc4-9d96-2df9a161b9c7', 'Which of the following is an example of an OUTPUT device?', 'mcq', 1, NULL, 'mock', 2025, 'Littoral Mock 2025', '5', NULL, 'A plotter is an output device that produces precise line drawings. It is used in CAD/engineering applications.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('70f00365-1d00-591f-a579-695238431e60', 'What does MICR stand for?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '6', NULL, 'MICR stands for Magnetic Ink Character Recognition. It reads characters printed in special magnetic ink, commonly used on bank cheques.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('44f5109d-e842-58fa-96b8-bb4983ed92c0', 'Which storage device is described as having the FASTEST access speed?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '7', NULL, 'Cache memory is the fastest storage device. It sits between the CPU and RAM to store frequently accessed instructions and data, reducing access time significantly.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('d8bc04a6-bc54-5478-8159-2c67bfd8db0f', 'The machine cycle consists of Fetch, Decode, and:', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '8', NULL, 'The machine cycle (instruction cycle) consists of three stages: Fetch (get instruction from RAM), Decode (interpret instruction), and Execute (carry out the instruction).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('0a036090-a6d8-5152-bb12-0c0dff9fafec', 'What type of data does the Data Bus carry?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '9', NULL, 'The Data Bus carries the actual data (instructions or values) between the CPU, memory, and other components. It is bidirectional.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('dc6ae485-bbeb-5e80-bc12-9dfa56f37635', 'Which of the following best describes ROM?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '10', NULL, 'ROM (Read-Only Memory) is non-volatile memory that permanently stores the BIOS/firmware. It cannot be modified by the user and retains data without power.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('aec76d9c-09e7-5347-81f5-1d847a5ebb12', 'An OMR device is BEST used for:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '11', NULL, 'OMR (Optical Mark Recognition) reads marks made on specifically designed forms. It is commonly used for multiple-choice exam answer sheets and survey forms.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('b285634b-37af-5aae-a123-b6dac4866493', 'Which unit of memory is the LARGEST?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '12', NULL, 'The order from smallest to largest is: Bit → Byte → KB → MB → GB → TB → PB. A Terabyte (TB) = 1024 GB, making it the largest in this list.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c5827969-d4c3-56ea-a737-92844bdd88b0', 'Which type of information system is used at the OPERATIONAL level of management?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '20', NULL, 'The TPS (Transaction Processing System) is used at the operational level. It handles day-to-day transactions like payroll, order processing, and stock control.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c0571e4d-2e88-566d-a1e9-f72d96a527cb', 'An information system that helps executives analyse long-term trends is a(n):', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '21', NULL, 'EIS (Executive Information System) is at the top of the management pyramid. It helps senior executives analyse trends and plan long-term strategies using both internal and external data.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('0238c44f-9b81-53f7-9381-a2dd1774380d', 'Which of the following BEST describes "data"?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '22', NULL, 'Data refers to raw, unprocessed facts and figures (e.g., numbers, characters) that have no meaning on their own until they are processed into information.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('a348d55b-efed-5637-9e11-1a88999af8d3', 'A school uses a system to track student attendance every morning. This is BEST described as a:', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '23', NULL, 'Attendance tracking is a routine, repetitive operation — this is a Transaction Processing System. TPS records daily operational data like attendance, sales, and payments.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('95a03ad2-13ae-52d2-b283-5414c9aa219c', 'The downward flow of information in an organisation typically contains:', 'mcq', 1, NULL, 'mock', 2025, 'Littoral Mock 2025', '24', NULL, 'In an organisation, downward information flow carries strategies, goals, directives, and policies from top management down to lower levels.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('7fc24bfb-4cf0-5a79-a669-b7decca91219', 'Which SDLC phase involves gathering requirements from users and analysing the current system?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '30', NULL, 'The Analysis phase involves investigating how the current system works, gathering user requirements through interviews/questionnaires, and producing a requirements specification.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('9bb305ec-f6bd-556e-b408-86de472fa87c', 'In which changeover method do both old and new systems run simultaneously?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '31', NULL, 'Parallel changeover runs both old and new systems at the same time. It is the safest method as the old system acts as backup, but it is the most expensive due to duplicate resources.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('ffa2436f-c565-5312-9a55-3f3e9047cae2', 'A Gantt chart is BEST described as:', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '32', NULL, 'A Gantt chart is a horizontal bar chart showing tasks against time. Each bar shows the start date, duration, and end date of a task. It is widely used for project scheduling.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('41703bee-7695-50dd-8c79-9deddb972f9c', 'The CRITICAL PATH in a project network is:', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '33', NULL, 'The critical path is the longest sequence of dependent tasks in the project. It determines the minimum time needed to complete the project. Tasks on this path have zero float (slack).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('345f6783-e27e-552e-85af-b0e4c4fa36d8', 'Which waterfall SDLC phase produces the actual executable code?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '34', NULL, 'The Development phase is where programmers actually write the code, create databases, and build the system based on design specifications.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('bc0ff72a-f410-5664-ad25-dabc85e4313b', 'An error that results in incorrect outcomes during execution is:', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '40', NULL, 'A logic error means the program runs without crashing but produces wrong results because the programmer''s algorithm or reasoning is flawed.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('6b02098e-c547-5137-b169-ee1a7acebb01', 'Which symbol is used to represent a DECISION in a flowchart?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '41', NULL, 'A diamond (rhombus) represents a decision point in a flowchart. It contains a yes/no question and has two output paths (True/False or Yes/No).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('cc4fe09c-f627-5286-8bc9-2633e43642cd', 'What does a COMPILER do?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '42', NULL, 'A compiler translates the entire high-level source code into machine code (object code) all at once. The resulting executable file can be run independently.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('90d190cf-60ee-54d9-9679-123ecb7dd950', 'Which control structure executes instructions based on whether a condition is TRUE or FALSE?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '43', NULL, 'Selection (conditional) structures like IF...THEN...ELSE allow different instructions to be executed depending on whether a condition evaluates to TRUE or FALSE.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('7db60aac-dd49-5ff9-8ad5-21cf4312bc3a', 'In pseudocode, which keyword is used to receive input from a user?', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '44', NULL, 'INPUT is the standard pseudocode keyword used to receive data from the user. For example: INPUT name. READ is used for reading from files.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('ef3f4e6e-969c-5d5a-beaa-8db0d96e349f', 'A WHILE loop in pseudocode checks its condition:', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '45', NULL, 'A WHILE loop is a pre-condition loop — it checks the condition BEFORE each iteration. If the condition is false initially, the loop body never executes.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('71c88857-9dff-51d1-87ec-69c25bf54c79', 'What is the output of the pseudocode: SET x = 3; FOR i = 1 TO 3; SET x = x + i; NEXT i; PRINT x', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '46', NULL, 'Step by step: x starts at 3. i=1: x=3+1=4. i=2: x=4+2=6. i=3: x=6+3=9. So x=9 is printed.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('88711dbc-cfd7-5597-89b8-c061b6a2b815', 'Which programming language type is CLOSEST to human language?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '47', NULL, 'High-level languages (e.g., Python, Java, C) use English-like commands and are closest to human language. They are portable and must be compiled or interpreted to run.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('5e9aff78-4f84-556c-95aa-b813bfd815a6', 'Which data type would BEST store a student''s exam score out of 100?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '48', NULL, 'An integer data type stores whole numbers, making it perfect for an exam score (e.g., 75, 88). Scores are whole numbers, not decimals or text.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('df974747-2581-5b49-aaae-3d43df712a53', 'An ARRAY is BEST described as:', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '49', NULL, 'An array is a collection of elements of the SAME data type stored in contiguous memory, accessed by an index number (starting from 0 or 1 depending on language).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('524326dc-658a-5eb5-8381-5b51527986af', 'Which sort algorithm works by repeatedly comparing and swapping adjacent elements?', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '50', NULL, 'Bubble Sort works by repeatedly comparing adjacent pairs of elements and swapping them if they are in the wrong order. This "bubbles" the largest values to the end.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('b1292407-c901-58e6-bf43-f5adb2868b2c', 'A field that UNIQUELY identifies each record in a table is called a:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '60', NULL, 'A Primary Key uniquely identifies each record in a database table. No two records can have the same primary key value, and it cannot be null (empty).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('0e7f1847-9181-58fa-b28e-7788e4a053a3', 'Which database model organises data into tables with rows and columns?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '61', NULL, 'The Relational Database model organises data into tables (relations) with rows (records) and columns (fields/attributes). Tables are linked using keys.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('bcb96044-9e75-5599-b56a-493278ddf503', 'In a database, a FOREIGN KEY is used to:', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '62', NULL, 'A Foreign Key is a field in one table that references (points to) the Primary Key of another table, establishing a relationship (link) between the two tables.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('7a6715c3-a130-591d-bc59-eca703cdd127', 'Which validation check ensures a numeric field value is between 1 and 100?', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '63', NULL, 'A Range Check verifies that a value falls within a specified range (e.g., 1 to 100). It rejects values outside this range.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('72a1ca76-519e-557f-a830-1e4fe7a179ac', 'What is NORMALISATION in database design?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '64', NULL, 'Normalisation is the process of structuring a database to minimise data redundancy (duplication) and prevent anomalies, thereby improving data integrity and consistency.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('670fc407-e192-5e8d-8618-19374e102cd8', 'Which network topology connects ALL devices to a CENTRAL hub or switch?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '70', NULL, 'In a Star topology, all devices (nodes) are connected to a central hub or switch. It is the most common network topology due to ease of management and fault isolation.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c7b3553b-91cc-594d-ba1d-a103c1e11bf1', 'A LAN (Local Area Network) typically covers:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '71', NULL, 'A LAN (Local Area Network) covers a small geographic area such as an office, building, or school campus. It is owned and managed by a single organisation.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('91f506c2-629d-56b3-811d-2514f3a1176e', 'Which device DIRECTS data packets between different networks?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '72', NULL, 'A Router connects different networks and directs (routes) data packets between them using IP addresses. It determines the best path for data to travel.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c5db378b-002a-5dba-8044-5bd91334effb', 'Which protocol is used to SEND email messages?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '73', NULL, 'SMTP (Simple Mail Transfer Protocol) is the protocol used for SENDING email messages from a client to a server, or between email servers.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('5d3b8fe8-6483-5e2b-9fb8-8eeee5f4c709', 'What does "HTTP" in a web address stand for?', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '74', NULL, 'HTTP stands for HyperText Transfer Protocol. It is the foundation protocol for data communication on the World Wide Web, defining how messages are formatted and transmitted.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('1b0ac109-ce90-5b32-9fd0-a7eb059ebcc1', 'Communication that allows data to travel in BOTH directions but NOT simultaneously is:', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '75', NULL, 'Half duplex allows bidirectional communication but only one direction at a time. A walkie-talkie is a classic example — only one person can speak at a time.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('ef635ad4-fbf0-5ef6-9457-a7f908a62521', 'Which of the following is a WIRELESS transmission medium?', 'mcq', 1, NULL, 'mock', 2025, 'Littoral Mock 2025', '76', NULL, 'Bluetooth is a wireless transmission medium using radio waves for short-range communication (typically up to 10 metres) between devices.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('3e973800-08ed-56e2-8673-a257ac2e9264', 'What is the purpose of DNS (Domain Name System)?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '77', NULL, 'DNS (Domain Name System) acts like the internet''s phone book — it translates human-readable domain names (e.g., www.google.com) into IP addresses that computers use.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('420db000-5f07-5de6-83a7-b5b8a7e643f8', 'What is 1011 in binary converted to decimal?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '80', NULL, '1011₂ = (1×8)+(0×4)+(1×2)+(1×1) = 8+0+2+1 = 11₁₀. Always multiply each bit by its place value (power of 2) and add.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('d3a42fa3-8da1-5b25-baab-a41ca21e7024', 'What is the decimal number 25 in binary?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '81', NULL, '25÷2=12r1, 12÷2=6r0, 6÷2=3r0, 3÷2=1r1, 1÷2=0r1. Reading remainders bottom to top: 11001₂.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c3e9ed25-b03c-5a3f-8d0c-faee7e6c0f15', 'What is the hexadecimal value of decimal 255?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '82', NULL, '255 ÷ 16 = 15 remainder 15. Both digits are 15 = F in hex. So 255₁₀ = FF₁₆. This is also the maximum value for one byte.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('110d28ea-27c5-5d84-9093-e24ec8b059a9', 'In the binary system, what is the place value of the LEFTMOST bit in an 8-bit number?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '83', NULL, 'In an 8-bit number, bit positions from right are 2⁰,2¹,2²,...,2⁷. The leftmost (most significant) bit has value 2⁷=128.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('0f72e3e9-41dc-56c9-937a-893c2ab6a58b', 'What is binary 1010 + binary 0110?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '84', NULL, '1010 + 0110: 0+0=0, 1+1=10(write 0 carry 1), 0+1+1(carry)=10(write 0 carry 1), 1+0+1(carry)=10. Result: 10000₂ = 16₁₀. Check: 10+6=16 ✓', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('97fe7552-57ec-506b-9240-947229225969', 'The hexadecimal digit "B" equals which decimal value?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '85', NULL, 'Hexadecimal uses A=10, B=11, C=12, D=13, E=14, F=15. So B₁₆ = 11₁₀.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('70b3d54a-7306-5937-b225-a3ee0ed6653f', 'An AND gate with inputs A=1 and B=0 gives an output of:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '90', NULL, 'AND gate rule: output is 1 ONLY IF all inputs are 1. Since B=0, the output is 0. Truth table: 1 AND 0 = 0.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('40804fd0-7387-501a-9b63-75d11ea1179b', 'Which logic gate gives output 1 ONLY when all inputs are 0?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '91', NULL, 'A NOR gate outputs 1 only when ALL inputs are 0. It is the inverse of OR. If any input is 1, the output is 0.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('1065590c-cb62-5d5c-bad0-e2458db19154', 'What is the output of a NOT gate when input A = 1?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '92', NULL, 'A NOT gate inverts (flips) its input. NOT 1 = 0. NOT 0 = 1. It is also called an inverter.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('49b90992-09a8-519f-a8e6-b837d73bea1a', 'De Morgan''s first law states that NOT(A AND B) is equivalent to:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '93', NULL, 'De Morgan''s First Law: NOT(A AND B) = (NOT A) OR (NOT B). This means a NAND gate is equivalent to an OR gate with inverted inputs.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('e49edba3-e83a-54ca-bf09-c8cdfb5df746', 'An XOR gate outputs 1 when:', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '94', NULL, 'XOR (Exclusive OR) gate outputs 1 ONLY when the inputs are DIFFERENT (0 and 1, or 1 and 0). When both inputs are the same (both 0 or both 1), the output is 0.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('ea5f985b-cad8-5238-9251-08d6bc1fe4f1', 'Which Act protects individuals'' personal data held by organisations?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '100', NULL, 'The Data Protection Act controls how personal data is collected, stored, and used. It gives individuals rights to see their own data and requires organisations to keep it accurate and secure.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('9275bca5-7e71-59f9-8b89-f9a1017a88b3', 'Using someone else''s computer password without their permission is an offence under the:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '101', NULL, 'The Computer Misuse Act makes it illegal to access computer material without authorisation. Using someone''s password without permission is unauthorised access under this law.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('a71e58fc-42f5-5097-a51e-5b7d659e03e2', 'Which of the following is a SOCIAL benefit of computers?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '102', NULL, 'Improved global communication is a social benefit — computers and the internet allow instant communication worldwide through email, social media, and video calls.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c4d32098-ce9f-5b3d-bc7c-ae453107ec42', 'Copying and distributing software without a licence is called:', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '103', NULL, 'Software piracy is the unauthorised copying, distribution, or use of software without proper licensing. It violates the Copyright, Design and Patent Act.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('4770bce4-8d6c-53f8-9be9-2d3062978521', 'What is ERGONOMICS?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '104', NULL, 'Ergonomics is the science of designing and arranging equipment, environments, and systems to fit the people who use them, improving comfort, efficiency, and safety.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('09bbbd34-0eb3-569c-b31d-ab3ea9a7c5a8', 'Which type of printer sprays tiny drops of ink onto paper?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '110', NULL, 'An inkjet printer works by spraying tiny droplets of liquid ink through microscopic nozzles onto the paper. It produces good quality colour prints.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('5305993a-d3ab-53f8-bc0d-501f498f6557', 'What is the purpose of an ACTUATOR in a control system?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '111', NULL, 'An actuator receives an electrical signal from the processor and converts it into a physical action (e.g., turning on a motor, opening a valve, switching a heater).', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('942ce31d-0a93-5d9b-ab46-35f061bcd22a', 'What does SSD stand for?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '112', NULL, 'SSD stands for Solid State Drive. Unlike HDDs, SSDs have no moving parts — they use flash memory chips. They are faster, more durable, and quieter but more expensive per GB.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('59c0ab0f-6371-5c62-a920-7f47de0a8282', 'A flight simulator used to train pilots is an example of:', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '120', NULL, 'A flight simulator is a simulation system — it imitates the real system (an aircraft) to train pilots in a safe, controlled environment without the risk and cost of real flights.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('43e8d0f4-c54e-56d7-a80f-6bd5a8d52bba', 'Which Excel tool allows you to specify a TARGET result and find the needed input?', 'mcq', 1, NULL, 'mock', 2024, 'HIHS Mock 2024', '121', NULL, 'Goal Seek (in Excel''s What-If Analysis) lets you specify a desired result and automatically calculates the input value needed to produce that result.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('6071d8a6-b2a8-529c-988d-480cd95b5c6a', 'What does DBMS stand for?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '130', NULL, 'DBMS stands for Database Management System — software that manages and organises databases. Examples include MySQL, Microsoft Access, Oracle, and PostgreSQL.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('d6e3511d-e870-5664-818e-890e09b9f350', 'In 1NF (First Normal Form), a table must:', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '131', NULL, 'First Normal Form (1NF) requires that all attributes are atomic (single, indivisible values) and there are no repeating groups or arrays within a single record.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('f0745501-c28e-59b7-85b3-13c79a893722', 'The DIGITAL DIVIDE refers to:', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '140', NULL, 'The Digital Divide is the inequality in access to digital technology between different groups — e.g., rich vs poor countries, urban vs rural areas. It creates educational and economic disadvantages.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('99b67514-66e3-5031-9497-e1b91b0c0996', 'Which RSI (Repetitive Strain Injury) prevention measure is MOST recommended?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '141', NULL, 'RSI is caused by repetitive movements. Prevention includes taking regular breaks (at least every hour), using wrist rests, and maintaining correct posture. These reduce strain on joints.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('f8219e28-1311-515e-ad21-9489fca83aed', 'Object-Oriented Programming organises code into:', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '150', NULL, 'OOP organises code into objects — self-contained units that combine data (properties/attributes) and behaviour (methods/functions). Key concepts: encapsulation, inheritance, polymorphism.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('3d7b2b5d-8e71-5737-a1c9-53f48a70f3b5', 'What is the MAIN advantage of using an INTERPRETER over a COMPILER?', 'mcq', 1, NULL, 'gce_past', NULL, 'GCE Past', '151', NULL, 'An interpreter translates and executes code one line at a time. When an error is found, it stops immediately and reports the error at that line — making debugging easier during development.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('c16359dc-26db-53d5-bd66-f51521968c98', 'A STACK data structure follows which principle?', 'mcq', 1, NULL, 'mock', 2025, 'HIHS Mock 2025', '152', NULL, 'A Stack uses LIFO (Last In, First Out) — the last item added (pushed) is the first item removed (popped). Think of a stack of plates: you add and remove from the top.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('630bb142-4a2f-571d-9764-e0ce8ea4140e', 'Which type of error occurs when the program breaks syntax rules?', 'mcq', 1, NULL, 'mock', 2026, 'SW Mock 2026', '153', NULL, 'A syntax error occurs when code violates the grammar rules of the programming language (e.g., missing bracket, misspelled keyword). The compiler/interpreter catches these before running.', NULL, true, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('8083788d-79d2-5ba6-8b42-96044b34521c', 'Information Systems & SDLC — HIHS Mock 2025 – Paper 2', 'structured', 30, NULL, 'mock', 2025, 'HIHS Mock 2025 – Paper 2', '1', NULL, NULL, 'RAINCO is a wholesale business specialising in two categories of umbrellas: Standard and Premium. Orders are placed by phone, with doorstep delivery. A minimum order of 25 umbrellas is required. RAINCO plans to expand by introducing online sales and adding two new categories: Sport and Travel. They want to implement a new computerised information system to manage this expansion.', false, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('28d758a6-f83f-52f9-b992-1c6532c0dd77', 'Algorithms, Programming & Data Types — HIHS Mock 2025 – Paper 2', 'structured', 25, NULL, 'mock', 2025, 'HIHS Mock 2025 – Paper 2', '2', NULL, NULL, 'A programmer is writing a program to process the scores of 10 students and determine the grade for each. Scores are out of 100.', false, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('fd2b7349-2813-5aa7-ac32-26bd5b1b3c95', 'Networks, Security & Communication — SW Mock 2026 – Paper 2', 'structured', 25, NULL, 'mock', 2026, 'SW Mock 2026 – Paper 2', '3', NULL, NULL, 'A school decides to set up a computer network connecting 30 computers in 3 classrooms. The school also wants to give students internet access and protect the network from external threats.', false, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('500cb1b8-24da-584e-8369-7e20a579f15a', 'Logic Gates & Number Systems — GCE & Mock Combined', 'structured', 20, NULL, 'mock', NULL, 'GCE & Mock Combined', '4', NULL, NULL, 'This question covers digital electronics and number systems — key components of the Computer Science syllabus.', false, false, 'teacher', 'high', 'ghs-mbonjo-static-2025'),
  ('3e466116-9083-5c59-89e0-e65c771a5d74', 'Computer Ethics, Legislation & Social Impact — GCE Past Questions', 'structured', 20, NULL, 'gce_past', NULL, 'GCE Past Questions', '5', NULL, NULL, 'This question examines your understanding of ethical, legal, and social issues arising from the use of computers and information technology.', false, false, 'teacher', 'high', 'ghs-mbonjo-static-2025')
) AS x(id, question_text, question_type, marks, difficulty, source, source_year, source_paper, source_number, model_answer, marking_guide, scenario, auto_markable, needs_review, answer_origin, answer_confidence, import_batch)
CROSS JOIN (SELECT id FROM syllabi
            WHERE form_level='Form 5' AND deleted_at IS NULL
            ORDER BY created_at LIMIT 1) AS target
ON CONFLICT (id) DO UPDATE SET
  question_text = EXCLUDED.question_text,
  marking_guide = EXCLUDED.marking_guide,
  scenario = EXCLUDED.scenario,
  updated_at = now();

